library(creditratingsystem)
for(helper in c(".cr_m_hmm_expectation",".cr_m_factor_filter",".cr_m_factor_moments"))if(!exists(helper,mode="function"))assign(helper,getFromNamespace(helper,"creditratingsystem"))
near_macro<-function(a,b,tol=1e-8)stopifnot(length(a)==length(b),all(abs(a-b)<=tol))
error_macro<-function(expr,code){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}
history_macro<-function(values){values<-as.matrix(values);n<-nrow(values);k<-ncol(values);dates<-sprintf('%04d-%02d-01',2000+(0:(n-1L))%/%12,(0:(n-1L))%%12+1L);list(dates=as.list(dates),values=lapply(seq_len(n),function(i)as.list(unname(values[i,]))),variable_ids=as.list(paste0('x',seq_len(k)-1L)),frequency='monthly',release_dates=lapply(dates,function(d)rep(list(d),k)),units=rep(list('index'),k))}
training_macro<-function(h)list(start=h$dates[[1]],end=tail(h$dates,1L)[[1]],known_at=tail(h$dates,1L)[[1]],split_id='macro_training',data_origin='SYNTHETIC')
