x_macro<-matrix(0,50,2)
for(i in 2:50)x_macro[i,]<-c(.2,-.1)+matrix(c(.6,.1,-.2,.4),ncol=2,byrow=TRUE)%*%x_macro[i-1L,]+c(sin(1.31*(i-1L)),cos(.73*(i-1L)))
h_macro<-history_macro(x_macro);var_macro<-fit_var(h_macro,2,'constant_trend',training=training_macro(h_macro),target=target_macro,model_id='var',model_version='1')
d_macro<-cbind(1,3:50,x_macro[2:49,],x_macro[1:48,]);oracle_macro<-solve(crossprod(d_macro),crossprod(d_macro,x_macro[3:50,]));near_macro(unlist(var_macro$model$parameters$intercept),oracle_macro[1,],1e-9);near_macro(unlist(var_macro$model$parameters$trend),oracle_macro[2,],1e-9)
r_macro<-x_macro[3:50,]-d_macro%*%oracle_macro;near_macro(unlist(var_macro$model$parameters$covariance),as.vector(t(crossprod(r_macro)/(48-6))),1e-10)
h<-history_macro(matrix(1.05^(0:19),ncol=1));unstable_macro<-fit_var(h,1,'none',training=training_macro(h),target=target_macro,model_id='explosive',model_version='1');near_macro(unstable_macro$diagnostics$spectral_radius,1.05);stopifnot(!unstable_macro$diagnostics$stable)
