i<-0:99;common<-cumsum(.1+sin(i*sqrt(2))+.3*sin(.13*i*i));stationary<-numeric(100)
for(t in 2:100)stationary[t]<-.3*stationary[t-1L]+.4*cos((t-1L)*sqrt(3))+.1*sin(.19*(t-1L)^2)
