forecast<-simulate_macro_scenarios(vecm_macro,cube)$value;near_macro(unlist(forecast$values),as.vector(t(cbind(expected[[1]][,'fcst'],expected[[2]][,'fcst']))),1e-8)
rank0_macro<-fit_vecm(cointegrated_macro,0,2,'constant_outside',training=training_macro(cointegrated_macro),target=target_macro,model_id='rank0',model_version='1');delta<-x[-1,]-x[-100,];d<-cbind(delta[-99,],1);b<-solve(crossprod(d),crossprod(d,delta[-1,]));near_macro(unlist(rank0_macro$model$parameters$lag_coefficients[[1]]),as.vector(t(diag(2)+t(b[1:2,]))),1e-8)
if(identical(tolower(Sys.getenv('CREDITRATINGSYSTEM_EXTENDED_TESTS')),'true'))for(det in c('none','constant_inside','constant_outside','constant_outside_trend_inside','constant_trend_outside'))for(lag in c(1,2)){
 fitted<-fit_vecm(cointegrated_macro,1,lag,det,training=training_macro(cointegrated_macro),target=target_macro,model_id='vecm',model_version='1');pred<-simulate_macro_scenarios(fitted,cube)$value;stopifnot(all(is.finite(unlist(pred$values))))
}
stationary_contract_macro<-list(law='STATIONARY_GAUSSIAN',cycle_law_id='AR1_equilibrium',equilibrium_assumptions='Stable time-homogeneous Gaussian AR1',initial_state_draws=list(list(1),list(-1)))
