hmm_y<-matrix(c(-1,.2,1),ncol=1);hmm_coef<-list(matrix(-1),matrix(1));hmm_cov<-list(matrix(.5),matrix(.8));hmm_p<-matrix(c(.8,.2,.1,.9),2,byrow=TRUE);hmm_initial<-c(.6,.4)
hmm_ex<-.cr_m_hmm_expectation(hmm_y,matrix(1,3,1),hmm_coef,hmm_cov,hmm_p,hmm_initial);hmm_states<-as.matrix(expand.grid(rep(list(1:2),3)));hmm_weights<-apply(hmm_states,1,function(state){w<-hmm_initial[state[1]];for(t in 1:3){if(t>1)w<-w*hmm_p[state[t-1],state[t]];w<-w*stats::dnorm(hmm_y[t,1],hmm_coef[[state[t]]][1,1],sqrt(hmm_cov[[state[t]]][1,1]))};w});near_macro(hmm_ex$ll,log(sum(hmm_weights)),1e-12)
for(t in 1:3)for(j in 1:2)near_macro(hmm_ex$gamma[t,j],sum(hmm_weights[hmm_states[,t]==j])/sum(hmm_weights),1e-12)
