factor_ll<--.5*(length(factor_flat)*log(2*pi)+as.numeric(determinant(factor_selected,logarithm=TRUE)$modulus)+as.numeric(crossprod(factor_flat-factor_mu,solve(factor_selected,factor_flat-factor_mu))));near_macro(factor_fit$ll,factor_ll,1e-10)
